class Solution {
    vector<vector<int>> grid;
    vector<int> match, seen;
    int rows, cols, stamp = 0;
    int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    bool augment(int id) {
        int r = id / cols, c = id % cols;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || !grid[nr][nc]) continue;
            int next = nr * cols + nc;
            if (seen[next] == stamp) continue;
            seen[next] = stamp;
            if (match[next] == -1 || augment(match[next])) {
                match[next] = id;
                return true;
            }
        }
        return false;
    }
public:
    int minimumOperations(vector<vector<int>>& input) {
        grid = input;
        rows = grid.size();
        cols = grid[0].size();
        match.assign(rows * cols, -1);
        seen.assign(rows * cols, 0);
        int answer = 0;
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] && (r + c) % 2 == 0) {
                    ++stamp;
                    if (augment(r * cols + c)) ++answer;
                }
            }
        }
        return answer;
    }
};
